<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * `transfers_load` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $LoadID
 * @property Carbon|null $ImportDate
 * @property int|null $cID_Customer
 * @property string|null $Pax
 * @property string|null $SupplierCode
 * @property string|null $TransferType
 * @property Carbon|null $TransferDate
 * @property string|null $TransferTime
 * @property string|null $From
 * @property string|null $To
 * @property string|null $Flight_Ship_Num_From
 * @property string|null $Notes
 * @property float|null $SalePrice
 * @property string|null $Assistant
 * @property string|null $PassengerList
 * @property string|null $CarType
 * @property string|null $LeadName
 * @property string|null $LeadPhone
 * @property float|null $SalePrice_C
 * @property float|null $Sale_Price
 * @property float|null $Sale_Price_Cleaned
 * @property string|null $Createdby
 * @property Carbon|null $CreatedDate
 * @property int|null $Loaded
 */
class TransfersLoad extends Model
{
    protected $table = 'transfers_load';

    protected $primaryKey = 'LoadID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'LoadID' => 'integer',
            'ImportDate' => 'date',
            'cID_Customer' => 'integer',
            'TransferDate' => 'date',
            'SalePrice' => 'float',
            'SalePrice_C' => 'float',
            'Sale_Price' => 'float',
            'Sale_Price_Cleaned' => 'float',
            'CreatedDate' => 'datetime',
            'Loaded' => 'integer',
        ];
    }

    public function priceLines(): HasMany
    {
        return $this->hasMany(PriceListLoad::class, 'LoadID', 'LoadID');
    }

    public function notes(): HasMany
    {
        return $this->hasMany(TransferNotesLoad::class, 'LoadID', 'LoadID');
    }

    /** myat_transfers_load_files.TransferID holds the LoadID. */
    public function files(): HasMany
    {
        return $this->hasMany(MyatTransfersLoadFile::class, 'TransferID', 'LoadID');
    }
}
